from typing import List

def minInsAndDel(N: int, M: int, A: List[int], B: List[int]) -> int:
    # Create a mapping from elements in B to their indices
    b_index_map = {value: index for index, value in enumerate(B)}

    # Transform A to only include elements that are in B, preserving order
    transformed_A = [b_index_map[x] for x in A if x in b_index_map]

    # Function to find the length of the Longest Increasing Subsequence (LIS)
    def lis(arr):
        if not arr:
            return 0

        # This will store the smallest tail of all increasing subsequences
        # with different lengths
        tails = []

        for num in arr:
            # Use binary search to find the insertion point of the current number
            left, right = 0, len(tails)
            while left < right:
                mid = (left + right) // 2
                if tails[mid] < num:
                    left = mid + 1
                else:
                    right = mid

            # If left is equal to the length of tails, it means num is greater than
            # any element in tails, so we can extend the largest subsequence
            if left == len(tails):
                tails.append(num)
            else:
                # Otherwise, replace the element at the found position
                tails[left] = num

        return len(tails)

    # Find the length of the LCS, which is the same as the LIS of transformed_A
    lcs_length = lis(transformed_A)

    # Calculate the minimum number of insertions and deletions
    return N + M - 2 * lcs_length
